diff --git a/include/linux/bpf_verifier.h b/include/linux/bpf_verifier.h
index 4c4e9358c146..0c622474efbc 100644
--- a/include/linux/bpf_verifier.h
+++ b/include/linux/bpf_verifier.h
@@ -16,6 +16,13 @@
 #define BPF_REGISTER_MAX_RANGE (1024 * 1024 * 1024)
 #define BPF_REGISTER_MIN_RANGE -1

+/* Maximum variable offset/size permitted when resolving memory accesses.
+ * This ensures that the 32-bit arithmetic used by the access checks cannot
+ * overflow when the offset and the access size are added.
+ */
+#define BPF_MAX_VAR_OFF	(1 << 29)
+#define BPF_MAX_VAR_SIZ	(1 << 29)
+
 struct bpf_reg_state {
 	enum bpf_reg_type type;
 	union {
diff --git a/kernel/bpf/verifier.c b/kernel/bpf/verifier.c
index 8b1ebe4c6aba..8e90a0a670c5 100644
--- a/kernel/bpf/verifier.c
+++ b/kernel/bpf/verifier.c
@@ -1072,6 +1072,11 @@ static int check_func_arg(struct bpf_verifier_env *env, u32 regno,
 			verbose("ARG_CONST_STACK_SIZE cannot be first argument\n");
 			return -EACCES;
 		}
+		if (reg->imm < 0 || reg->imm >= BPF_MAX_VAR_SIZ) {
+			verbose("R%d unbounded memory access, use 'var &= const' or 'if (var < const)'\n",
+				regno);
+			return -EACCES;
+		}
 		if (regs[regno - 1].type == PTR_TO_PACKET)
 			err = check_packet_access(env, regno - 1, 0, reg->imm);
 		else
@@ -1565,6 +1570,20 @@ static void check_reg_overflow(struct bpf_reg_state *reg)
 		reg->min_value = BPF_REGISTER_MIN_RANGE;
 }

+static bool check_reg_sane_offset(struct bpf_verifier_env *env,
+				  const struct bpf_reg_state *reg,
+				  enum bpf_reg_type type)
+{
+	if (reg->type == CONST_IMM &&
+	    (reg->imm >= BPF_MAX_VAR_OFF || reg->imm <= -BPF_MAX_VAR_OFF)) {
+		verbose("math between %s pointer and %lld is not allowed\n",
+			reg_type_str[type], reg->imm);
+		return false;
+	}
+
+	return true;
+}
+
 static void adjust_reg_min_max_vals(struct bpf_verifier_env *env,
 				    struct bpf_insn *insn)
 {
@@ -1597,6 +1616,17 @@ static void adjust_reg_min_max_vals(struct bpf_verifier_env *env,
 		min_set = max_set = true;
 	}

+	/* Reduce the scope of scalar op scalar tracking: when the source is
+	 * not a known constant only ADD, SUB and AND can derive sound bounds.
+	 * For everything else the destination must be treated as unknown.
+	 */
+	if (BPF_SRC(insn->code) == BPF_X &&
+	    regs[insn->src_reg].type != CONST_IMM &&
+	    opcode != BPF_ADD && opcode != BPF_SUB && opcode != BPF_AND) {
+		reset_reg_range_values(regs, insn->dst_reg);
+		return;
+	}
+
 	/* We don't know anything about what was done to this register, mark it
 	 * as unknown. Also, if both derived bounds came from signed/unsigned
 	 * mixed compares and one side is unbounded, we cannot really do anything
@@ -1853,6 +1883,27 @@ static int check_alu_op(struct bpf_verifier_env *env, struct bpf_insn *insn)

 		dst_reg = &regs[insn->dst_reg];

+		/* Pointer arithmetic must not combine a pointer with a scalar
+		 * whose known value is out of range; otherwise the 32-bit
+		 * arithmetic used by the memory access checks can overflow or
+		 * truncate the resulting offset.
+		 */
+		if (BPF_CLASS(insn->code) == BPF_ALU64 &&
+		    (opcode == BPF_ADD || opcode == BPF_SUB) &&
+		    is_pointer_value(env, insn->dst_reg)) {
+			if (BPF_SRC(insn->code) == BPF_X) {
+				if (!check_reg_sane_offset(env,
+							   &regs[insn->src_reg],
+							   dst_reg->type))
+					return -EINVAL;
+			} else if (insn->imm >= BPF_MAX_VAR_OFF ||
+				   insn->imm <= -BPF_MAX_VAR_OFF) {
+				verbose("math between %s pointer and %d is not allowed\n",
+					reg_type_str[dst_reg->type], insn->imm);
+				return -EINVAL;
+			}
+		}
+
 		/* first we want to adjust our ranges. */
 		adjust_reg_min_max_vals(env, insn);
